import assert from 'node:assert/strict';
import { randomUUID } from 'node:crypto';
import type { Server } from 'node:http';
import { after, before, beforeEach, test } from 'node:test';
import { ClientSession, ObjectId } from 'mongodb';
import { createApp } from '../../src/app';
import { editAdminPageItem, getAdminPage } from '../../src/administration/catalog/adminCatalogService';
import { getDb } from '../../src/infrastructure/database';
import { Page } from '../../src/models/page';
import { createSession } from '../../src/services/auth/authSessionService';
import { reorderAdminPage } from '../../src/services/content/adminPageOrderService';
import { deleteCarouselAndPageReferences } from '../../src/services/content/pageReferenceLifecycleService';
import { startMongoReplicaSet, type MongoReplicaSetHarness } from '../support/mongoReplicaSet';

let harness: MongoReplicaSetHarness, server: Server, base = '', token = '', userToken = '';
const admin = new ObjectId(), secondAdmin = new ObjectId(), user = new ObjectId();
const actor = admin.toHexString();
const db = () => getDb()!;
const code = (expected: string) => (error: any) => error.code === expected;
const storedPage = () => db().collection('pages').findOne({ slug: 'home' });

/** Sends only synthetic administrator orders to the isolated application. */
const request = (body: unknown, access = token, headers: Record<string, string> = {}) => fetch(base + '/api/admin/v1/pages/home/reorder', {
    method: 'POST', headers: { ...(access ? { Authorization: `Bearer ${access}` } : {}), 'Content-Type': 'application/json', ...headers },
    body: JSON.stringify(body)
});

/** Mixes persisted and legacy identities with hidden, missing and unsupported references. */
const seedPage = async () => {
    const carousel = new ObjectId(), grid = new ObjectId(), unsupported = new ObjectId(), missing = new ObjectId();
    const first = new ObjectId().toHexString(), third = new ObjectId().toHexString(), fourth = new ObjectId().toHexString();
    await db().collection('carousels').insertOne({ _id: carousel, name: 'Synthetic picks', mode: 'manual', items: [] });
    await db().collection('contentCollections').insertMany([
        { _id: grid, name: 'Synthetic hidden Grid', mode: 'manual', presentation: 'grid', items: [] },
        { _id: unsupported, name: 'Synthetic unsupported List', mode: 'manual', presentation: 'grid', items: [] }
    ]);
    const items = [
        { itemId: first, itemType: 'carousel', carouselId: carousel.toHexString(), order: 0, adminNote: 'private-configuration' },
        { itemType: 'grid', collectionId: grid.toHexString(), order: 1, visibility: 'hidden' },
        { itemId: third, itemType: 'list', collectionId: missing.toHexString(), order: 2 },
        { itemId: fourth, itemType: 'list', collectionId: unsupported.toHexString(), order: 3 }
    ];
    await db().collection('pages').insertOne({ slug: 'home', title: 'Synthetic Home', items, createdBy: 'private-provenance' });
    const page = (await getAdminPage(actor, 'home')).page;
    const itemIds = [fourth, third, grid.toHexString(), first];
    return { page, items, carousel, grid, unsupported, itemIds,
        body: { operationId: randomUUID(), expectedRevision: page.revision, itemIds } };
};

before(async () => {
    harness = await startMongoReplicaSet('archtree-admin-page-order-test');
    server = await new Promise(resolve => { const active = createApp().listen(0, '127.0.0.1', () => resolve(active)); });
    const address = server.address(); assert.ok(address && typeof address !== 'string'); base = `http://127.0.0.1:${address.port}`;
});
beforeEach(async () => {
    for (const name of ['users', 'authSessions', 'pages', 'carousels', 'contentCollections', 'adminCatalogMutations']) {
        await db().collection(name).deleteMany({});
    }
    const administrator = { _id: admin, role: 'admin', emailVerified: true, email: 'page-admin@example.test' };
    const ordinary = { _id: user, role: 'user', emailVerified: true, email: 'page-user@example.test' };
    await db().collection('users').insertMany([administrator, ordinary,
        { _id: secondAdmin, role: 'admin', emailVerified: true, email: 'page-other-admin@example.test' }]);
    token = (await createSession(administrator)).accessToken; userToken = (await createSession(ordinary)).accessToken;
});
after(async () => {
    await new Promise<void>(resolve => server?.close(() => resolve())); await harness?.stop();
});

test('the administrator endpoint saves one complete order, preserving hidden and broken placements with an allowlisted receipt', async () => {
    const { body, items, page, itemIds } = await seedPage();
    const response = await request(body); assert.equal(response.status, 200);
    assert.match(response.headers.get('cache-control')!, /no-store/);
    const saved: any = await response.json();
    assert.deepEqual(saved.receipt, { operationId: body.operationId });
    assert.deepEqual(saved.page.items.map((item: any) => item.itemId), itemIds);
    assert.deepEqual(saved.page.items.map((item: any) => item.order), [0, 1, 2, 3]);
    assert.deepEqual(saved.page.items.map((item: any) => item.referenceStatus), ['unsupported', 'missing', 'ready', 'ready']);
    assert.equal(saved.page.items[2].visibility, 'hidden'); assert.notEqual(saved.page.revision, page.revision);
    assert.deepEqual(saved.page, (await getAdminPage(actor, 'home')).page);
    const stored = (await storedPage())!;
    assert.deepEqual(stored.items, [items[3], items[2], items[1], items[0]].map((item, order) => ({
        ...item, itemId: itemIds[order], order
    })));
    assert.equal(stored.updatedBy, actor); assert.equal(await db().collection('adminCatalogMutations').countDocuments(), 1);
    for (const privateField of ['private-configuration', 'private-provenance', 'updatedBy', 'createdBy', 'referenceRevision', 's3Key']) {
        assert.equal(JSON.stringify(saved).includes(privateField), false, privateField);
    }
    assert.deepEqual((await db().collection('carousels').findOne({ _id: new ObjectId(items[0].carouselId!) }))!.items, []);
});

test('unauthorized, revoked and mismatched-viewer requests cannot reorder or replay a receipt', async () => {
    const { body } = await seedPage(); const before = await storedPage();
    assert.equal((await request(body, '')).status, 401);
    assert.equal((await request(body, userToken)).status, 403);
    assert.equal((await request(body, '', { Cookie: `session_token=${token}`, Origin: base })).status, 409);
    assert.equal((await request(body, '', { Cookie: `session_token=${token}`, Origin: base, 'X-Finitude-Account-Viewer': user.toHexString() })).status, 409);
    assert.deepEqual(await storedPage(), before); assert.equal(await db().collection('adminCatalogMutations').countDocuments(), 0);
    const saved = await reorderAdminPage(actor, 'home', body);
    await db().collection('users').updateOne({ _id: admin }, { $set: { role: 'user' } });
    assert.equal((await request(body)).status, 403);
    await assert.rejects(reorderAdminPage(actor, 'home', body), code('ADMIN_PERMISSION_REQUIRED'));
    assert.deepEqual((await storedPage())!.items.map((item: any) => item.itemId), saved.page.items.map((item: any) => item.itemId));
    await db().collection('users').updateOne({ _id: admin }, { $set: { role: 'admin' } });
    await db().collection('authSessions').updateMany({ userId: actor }, { $set: { revokedAt: new Date() } });
    assert.equal((await request(body)).status, 401);
});

test('malformed, duplicate, incomplete and foreign orders are rejected without replacing the stored array', async () => {
    const { body } = await seedPage(); const before = await storedPage();
    const invalid = [null, [], {}, { ...body, extra: true }, { ...body, expectedRevision: 1 }, { ...body, operationId: 'invalid' },
        { ...body, itemIds: null }, { ...body, itemIds: [null] }, { ...body, itemIds: ['0'.repeat(23)] },
        { ...body, itemIds: ['A'.repeat(24)] }, { ...body, itemIds: [body.itemIds[0], body.itemIds[0]] },
        { ...body, itemIds: body.itemIds.slice(1) }, { ...body, itemIds: [] },
        { ...body, itemIds: [new ObjectId().toHexString(), ...body.itemIds.slice(1)] },
        { ...body, itemIds: Array.from({ length: 1001 }, () => new ObjectId().toHexString()) }];
    for (const raw of invalid) {
        await assert.rejects(async () => reorderAdminPage(actor, 'home', raw), code('ADMIN_CATALOG_INVALID_INPUT'));
        assert.deepEqual(await storedPage(), before);
    }
    await assert.rejects(async () => reorderAdminPage(actor, 'other', body), code('ADMIN_CATALOG_INVALID_INPUT'));
    await assert.rejects(reorderAdminPage(actor, 'library', body), code('ADMIN_CATALOG_NOT_FOUND'));
    assert.equal(await db().collection('adminCatalogMutations').countDocuments(), 0);
});

test('ambiguous legacy or persisted identities and DTO-omitted records block the entire order', async () => {
    const { items } = await seedPage();
    const damaged = [
        [items[0], { ...items[0] }],
        [{ itemType: 'grid', collectionId: items[1].collectionId, order: 0 }, { ...items[1] }],
        [items[0], { itemType: 'grid', collectionId: 'unrecognizable', order: 1 }],
        [items[0], { itemId: new ObjectId().toHexString(), itemType: 'unknown', order: 1 }],
        [items[0], null],
        'malformed-array'
    ];
    for (const rawItems of damaged) {
        await db().collection('pages').updateOne({ slug: 'home' }, { $set: { items: rawItems } });
        const page = (await getAdminPage(actor, 'home')).page, before = await storedPage();
        const visibleIds = [...new Set<string>(page.items.map((item: any) => item.itemId))];
        await assert.rejects(reorderAdminPage(actor, 'home', {
            operationId: randomUUID(), expectedRevision: page.revision, itemIds: visibleIds.reverse()
        }), code('ADMIN_PAGE_ITEM_IDENTITY_CONFLICT'));
        assert.deepEqual(await storedPage(), before);
    }
    assert.equal(await db().collection('adminCatalogMutations').countDocuments(), 0);
});

test('exact retry replays its original page after later edits while changed intent and other actors cannot replay it', async () => {
    const { body } = await seedPage();
    const saved = await reorderAdminPage(actor, 'home', body);
    await editAdminPageItem(actor, 'home', body.itemIds[0], {
        operationId: randomUUID(), expectedRevision: saved.page.revision, visibility: 'hidden'
    });
    const current = await storedPage();
    assert.deepEqual(await reorderAdminPage(actor, 'home', { ...body }), saved);
    assert.deepEqual(await storedPage(), current);
    for (const changed of [{ ...body, itemIds: [...body.itemIds].reverse() },
        { ...body, expectedRevision: (await getAdminPage(actor, 'home')).page.revision }]) {
        await assert.rejects(reorderAdminPage(actor, 'home', changed), code('ADMIN_CATALOG_IDEMPOTENCY_CONFLICT'));
    }
    await assert.rejects(reorderAdminPage(secondAdmin.toHexString(), 'home', body), code('ADMIN_CATALOG_REVISION_CONFLICT'));
    assert.equal(await db().collection('adminCatalogMutations').countDocuments({ operationId: body.operationId }), 1);
});

test('input arrays are captured before asynchronous admission and concurrent identical submissions commit one receipt', async () => {
    const { body } = await seedPage(), approved = [...body.itemIds];
    const first = reorderAdminPage(actor, 'home', body);
    body.itemIds.reverse();
    const second = reorderAdminPage(actor, 'home', { ...body, itemIds: approved });
    const results = await Promise.all([first, second]); assert.deepEqual(results[0], results[1]);
    assert.deepEqual(results[0].page.items.map((item: any) => item.itemId), approved);
    assert.equal(await db().collection('adminCatalogMutations').countDocuments(), 1);
});

test('a committed order whose response is lost is recovered from the same receipt without another write', async t => {
    const { body } = await seedPage();
    const original = ClientSession.prototype.withTransaction; let lost = true;
    t.mock.method(ClientSession.prototype, 'withTransaction', async function (this: ClientSession, ...args: Parameters<ClientSession['withTransaction']>) {
        const result = await original.apply(this, args);
        if (lost) { lost = false; throw new Error('Synthetic lost commit response'); }
        return result;
    });
    await assert.rejects(reorderAdminPage(actor, 'home', body), /Synthetic lost commit response/);
    const committed = await storedPage(), replayed = await reorderAdminPage(actor, 'home', body);
    assert.deepEqual(await storedPage(), committed);
    assert.deepEqual(replayed.receipt, { operationId: body.operationId });
    assert.deepEqual(replayed.page.items.map((item: any) => item.itemId), body.itemIds);
    assert.equal(await db().collection('adminCatalogMutations').countDocuments(), 1);
});

test('receipt refusal rolls back the whole order, identity backfill and reference fences', async () => {
    const { body } = await seedPage();
    await db().collection('adminCatalogMutations').insertMany(Array.from({ length: 256 }, () => ({
        actor, operationId: randomUUID(), fingerprint: 'synthetic', result: null, expiresAt: new Date(Date.now() + 86_400_000)
    })));
    const before = await storedPage(), carousels = await db().collection('carousels').find().toArray();
    const collections = await db().collection('contentCollections').find().toArray();
    await assert.rejects(reorderAdminPage(actor, 'home', body), code('ADMIN_CATALOG_RECEIPT_LIMIT'));
    assert.deepEqual(await storedPage(), before);
    assert.deepEqual(await db().collection('carousels').find().toArray(), carousels);
    assert.deepEqual(await db().collection('contentCollections').find().toArray(), collections);
    assert.equal(await db().collection('adminCatalogMutations').countDocuments(), 256);
});

test('Page, definition and legacy composition changes all invalidate a captured order', async () => {
    const { carousel, items } = await seedPage();
    const changes = [
        () => db().collection('pages').updateOne({ slug: 'home' }, { $set: { title: 'Concurrent title' } }),
        () => db().collection('carousels').updateOne({ _id: carousel }, { $set: { name: 'Concurrent name' } }),
        () => db().collection('carousels').updateOne({ _id: carousel }, { $set: { mode: 'artist' } }),
        async () => { const page = (await getAdminPage(actor, 'home')).page;
            await editAdminPageItem(actor, 'home', items[0].itemId!, { operationId: randomUUID(), expectedRevision: page.revision, visibility: 'hidden' }); },
        () => Page.reorderItem('home', 0, 1, actor),
        () => Page.removeCarouselItem('home', carousel.toHexString(), actor)
    ];
    for (const change of changes) {
        const page = (await getAdminPage(actor, 'home')).page;
        await change();
        const before = await storedPage(), receiptCount = await db().collection('adminCatalogMutations').countDocuments();
        await assert.rejects(reorderAdminPage(actor, 'home', {
            operationId: randomUUID(), expectedRevision: page.revision, itemIds: page.items.map((item: any) => item.itemId).reverse()
        }), code('ADMIN_CATALOG_REVISION_CONFLICT'));
        assert.deepEqual(await storedPage(), before);
        assert.equal(await db().collection('adminCatalogMutations').countDocuments(), receiptCount);
    }
});

test('concurrent visibility and order approvals at the same revision cannot both commit', async () => {
    const { body, items } = await seedPage();
    const outcomes = await Promise.allSettled([
        reorderAdminPage(actor, 'home', body),
        editAdminPageItem(secondAdmin.toHexString(), 'home', items[0].itemId!, {
            operationId: randomUUID(), expectedRevision: body.expectedRevision, visibility: 'hidden'
        })
    ]);
    assert.equal(outcomes.filter(result => result.status === 'fulfilled').length, 1);
    assert.ok(outcomes.some(result => result.status === 'rejected' && code('ADMIN_CATALOG_REVISION_CONFLICT')(result.reason)));
    assert.equal(await db().collection('adminCatalogMutations').countDocuments(), 1);
    const page = (await getAdminPage(actor, 'home')).page;
    const oldIds = items.map((item: any) => item.itemId ?? item.collectionId);
    assert.deepEqual(page.items.map((item: any) => item.itemId), outcomes[0].status === 'fulfilled' ? body.itemIds : oldIds);
    await assert.rejects(editAdminPageItem(actor, 'home', items[0].itemId!, {
        operationId: randomUUID(), expectedRevision: body.expectedRevision, visibility: 'hidden'
    }), code('ADMIN_CATALOG_REVISION_CONFLICT'));
});

test('concurrent target deletion never lets an order resurrect the detached placement', async () => {
    const { body, carousel } = await seedPage();
    const outcomes = await Promise.allSettled([
        reorderAdminPage(actor, 'home', body),
        deleteCarouselAndPageReferences(carousel.toHexString(), secondAdmin.toHexString())
    ]);
    assert.equal(outcomes[1].status, 'fulfilled');
    if (outcomes[0].status === 'rejected') assert.ok(code('ADMIN_CATALOG_REVISION_CONFLICT')(outcomes[0].reason));
    assert.equal(await db().collection('carousels').findOne({ _id: carousel }), null);
    const page = (await storedPage())!;
    assert.equal(page.items.length, 3); assert.equal(page.items.some((item: any) => item.carouselId === carousel.toHexString()), false);
    assert.deepEqual(page.items.map((item: any) => item.order), [0, 1, 2]);
});
